// Keep the account anchor steady while earlier demo content finishes expanding.
let cancelAccountPreviewScroll;
function scrollToAccountPreview(reducedMotion) {
  cancelAccountPreviewScroll?.();
  const target = document.getElementById("account-preview");
  if (!target) return;
  if (reducedMotion) {
    target.scrollIntoView({behavior: "instant", block: "start"});
    return;
  }
  let landed = false, cancelled = false, frame;
  const offset = parseFloat(getComputedStyle(target).scrollMarginTop) || 0;
  const align = () => {
    if (!landed || cancelled) return;
    cancelAnimationFrame(frame);
    frame = requestAnimationFrame(() => {
      const delta = target.getBoundingClientRect().top - offset;
      if (Math.abs(delta) > 1) window.scrollBy({top: delta, behavior: "instant"});
    });
  };
  const settle = () => { landed = true; align(); };
  const observer = new ResizeObserver(align);
  const cancel = () => {
    cancelled = true;
    observer.disconnect();
    cancelAnimationFrame(frame);
    clearTimeout(fallback);
    clearTimeout(expiry);
    window.removeEventListener("scrollend", settle);
    for (const event of ["wheel", "touchstart", "pointerdown", "keydown"])
      window.removeEventListener(event, cancel, true);
    if (cancelAccountPreviewScroll === cancel) cancelAccountPreviewScroll = null;
  };
  const fallback = setTimeout(settle, 1500);
  const expiry = setTimeout(cancel, 10000);
  cancelAccountPreviewScroll = cancel;
  observer.observe(target.closest("main"));
  window.addEventListener("scrollend", settle);
  // Any deliberate interaction returns scrolling control immediately to the visitor.
  for (const event of ["wheel", "touchstart", "pointerdown", "keydown"])
    window.addEventListener(event, cancel, {capture: true, passive: true});
  target.scrollIntoView({behavior: "smooth", block: "start"});
}

